import {probeAtlasRecordTexels} from './reflection-probe-record.js';
import {ShaderChunk} from 'three';
import {probeBlendGLSL} from './reflection-probe-blend.js';

const source=ShaderChunk.cube_uv_reflection_fragment,start=source.indexOf('vec3 bilinearCubeUV'),end=source.indexOf('#define cubeUV_r0');
if(start<0||end<=start)throw Error('Three CubeUV 아틀라스 샘플러를 확인하세요.');
const sampler=source.slice(start,end).replace('bilinearCubeUV( sampler2D envMap, vec3 direction, float mipInt )','hbAtlasBilinear( sampler2D envMap, vec3 direction, float mipInt, vec3 cubeLayout, vec4 rect )').replaceAll('CUBEUV_MAX_MIP','cubeLayout.z').replaceAll('CUBEUV_TEXEL_WIDTH','cubeLayout.x').replaceAll('CUBEUV_TEXEL_HEIGHT','cubeLayout.y').replace('uv.y *= cubeLayout.y;','uv.y *= cubeLayout.y;\nuv=rect.xy+uv*rect.zw;');
const globals=`
#ifdef ENVMAP_TYPE_CUBE_UV
uniform sampler2D hbProbeAtlas,hbProbeTable;uniform int hbProbeAtlasCount,hbProbeTableWidth;uniform bool hbProbeAtlasInfluence;
struct HBAtlasProbe{vec4 center,minimum,maximum,localX,localY,localZ,faceScale,cubeLayout,rect,projectionMinimum,projectionMaximum,projectionX,projectionY,projectionZ,blendPositive,blendNegative,fadePositive,fadeNegative,normalPositive,normalNegative;};
vec4 hbAtlasLoad(int index,int field){int at=index*${probeAtlasRecordTexels}+field;return texelFetch(hbProbeTable,ivec2(at%hbProbeTableWidth,at/hbProbeTableWidth),0);}
HBAtlasProbe hbAtlasProbe(int i){return HBAtlasProbe(hbAtlasLoad(i,0),hbAtlasLoad(i,1),hbAtlasLoad(i,2),hbAtlasLoad(i,3),hbAtlasLoad(i,4),hbAtlasLoad(i,5),hbAtlasLoad(i,6),hbAtlasLoad(i,7),hbAtlasLoad(i,8),hbAtlasLoad(i,9),hbAtlasLoad(i,10),hbAtlasLoad(i,11),hbAtlasLoad(i,12),hbAtlasLoad(i,13),hbAtlasLoad(i,14),hbAtlasLoad(i,15),hbAtlasLoad(i,16),hbAtlasLoad(i,17),hbAtlasLoad(i,18),hbAtlasLoad(i,19));}
int hbAtlasFirst=-1,hbAtlasSecond=-1;vec2 hbAtlasWeights=vec2(0);
int hbAtlasWord(float lo,float hi){return int(lo)+int(hi)*65536;}
void hbAtlasChoose(vec3 normal,vec3 ray){hbAtlasFirst=-1;hbAtlasSecond=-1;hbAtlasWeights=vec2(0);int cursor=0,total=hbProbeAtlasCount*2-1;float firstFlags=0.0;while(cursor<total){vec4 lower=hbAtlasLoad(hbProbeAtlasCount,cursor*3),upper=hbAtlasLoad(hbProbeAtlasCount,cursor*3+1),meta=hbAtlasLoad(hbProbeAtlasCount,cursor*3+2);int skip=hbAtlasWord(lower.w,upper.w),rank=hbAtlasWord(meta.z,meta.w);if(any(lessThan(hbProbePosition,lower.xyz))||any(greaterThan(hbProbePosition,upper.xyz))||(hbAtlasSecond>=0&&rank>=hbAtlasSecond)){cursor=skip;continue;}int leaf=hbAtlasWord(meta.x,meta.y);if(leaf>0){int i=leaf-1;vec4 lo=hbAtlasLoad(i,1),hi=hbAtlasLoad(i,2),x=hbAtlasLoad(i,3),y=hbAtlasLoad(i,4),z=hbAtlasLoad(i,5),scale=hbAtlasLoad(i,6);float weight=hbProbeInfluenceFade(hbProbeLocalPoint(hbProbePosition,x,y,z),lo.xyz,hi.xyz,scale.xyz,lo.w,mod(scale.w,4.0)>1.5,hbProbePosition,hbAtlasLoad(i,0).xyz,normal,ray,hbAtlasLoad(i,14),hbAtlasLoad(i,15),hbAtlasLoad(i,16),hbAtlasLoad(i,17),hbAtlasLoad(i,18),hbAtlasLoad(i,19),x,y,z);if(weight>0.0){if(hbAtlasFirst<0||i<hbAtlasFirst){hbAtlasSecond=hbAtlasFirst;hbAtlasWeights.y=hbAtlasWeights.x;hbAtlasFirst=i;hbAtlasWeights.x=weight;firstFlags=scale.w;}else if(hbAtlasSecond<0||i<hbAtlasSecond){hbAtlasSecond=i;hbAtlasWeights.y=weight;}}}cursor++;}if(firstFlags>=4.0)hbAtlasWeights.y*=1.0-hbAtlasWeights.x;}
`+sampler+String.raw`
vec3 hbAtlasSample(HBAtlasProbe p,vec3 ray,float roughness){float mip=clamp(roughnessToMip(roughness),cubeUV_m0,p.cubeLayout.z),whole=floor(mip),part=fract(mip);vec3 first=hbAtlasBilinear(hbProbeAtlas,ray,whole,p.cubeLayout.xyz,p.rect);return part==0.0?first:mix(first,hbAtlasBilinear(hbProbeAtlas,ray,whole+1.0,p.cubeLayout.xyz,p.rect),part);}
vec3 hbAtlasLight(vec3 ray,float roughness,bool diffuse,vec3 normal){if(hbProbeAtlasInfluence)hbAtlasChoose(normal,ray);float total=hbAtlasWeights.x+hbAtlasWeights.y;vec3 light=vec3(0);for(int slot=0;slot<2;slot++){int index=slot==0?hbAtlasFirst:hbAtlasSecond;if(index<0)continue;HBAtlasProbe p=hbAtlasProbe(index);vec3 direction=ray;if(!diffuse&&mod(p.faceScale.w,2.0)>.5)direction=p.projectionMinimum.w>.5?hbProxyDirection(hbProbePosition,ray,p.center.xyz,p.projectionMinimum,p.projectionMaximum,p.projectionX,p.projectionY,p.projectionZ):mod(p.faceScale.w,4.0)>1.5?hbProbeSphereProject(hbProbePosition,ray,p.center.xyz,hbProbeLocalPoint(hbProbePosition,p.localX,p.localY,p.localZ),hbProbeLocalRay(ray,p.localX,p.localY,p.localZ),p.maximum.x):hbProbeProject(hbProbePosition,ray,p.center.xyz,hbProbeLocalPoint(hbProbePosition,p.localX,p.localY,p.localZ),hbProbeLocalRay(ray,p.localX,p.localY,p.localZ),p.minimum.xyz,p.maximum.xyz);vec3 sampleColor=hbAtlasSample(p,direction,roughness)*p.center.w;
#ifdef USE_LIGHTMAP
if(!diffuse&&hbProbeLightmapMixing&&lightMapIntensity>0.0&&roughness>.1&&dot(normal,normal)>0.0)sampleColor*=hbProbeLightmapScale(PI*hbAtlasSample(p,normal,1.0)*p.center.w,roughness);
#endif
light+=sampleColor*(diffuse?p.maximum.w:1.0)*(slot==0?hbAtlasWeights.x:hbAtlasWeights.y);}light/=max(1.0,total);if(hbProbeBaseOptions.x>.5&&total<1.0)light+=hbProbeSample(hbProbeBaseMap,hbProbeBaseRotation*ray,roughness,hbProbeBaseLayout)*hbProbeBaseOptions.y*(1.0-total);return light;}
vec3 hbAtlasLight(vec3 ray,float roughness,bool diffuse){return hbAtlasLight(ray,roughness,diffuse,vec3(0));}
#endif
`;
export function probeAtlasPhysicalGLSL(){return probeBlendGLSL+'\n'+globals+'\n'+ShaderChunk.envmap_physical_pars_fragment.replace(/vec4 envMapColor = textureCubeUV\([^;]+;/g,'').replace('return PI * envMapColor.rgb * envMapIntensity;','return PI * hbAtlasLight(worldNormal,1.0,true,worldNormal);').replace('return envMapColor.rgb * envMapIntensity;','return hbAtlasLight(reflectVec,roughness,false,inverseTransformDirection(normal,viewMatrix));');}
